custom_css:
/*
 * 玉兰 · 功能、焦点、状态保护
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */

body {
    color: var(--yl-paper);
    background-color: var(--yl-ink);
    font-family: var(--yl-font-body);
    text-shadow: none;
}

#bg1,
#bg_custom {
    background-color: #110b0b;
    background-image: var(--yl-background-image);
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
}

:is(
    #top-settings-holder,
    #chat,
    #send_form,
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(button, input, textarea, select, [tabindex]):focus-visible {
    outline: 2px solid var(--yl-apricot);
    outline-offset: 2px;
}

#top-settings-holder .drawer-icon::before,
#send_form::before,
#send_form::after,
#options_button::after,
#extensionsMenuButton::after,
#send_but::after,
#mes_stop::after {
    pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
    :is(#chat, #top-bar, #send_form, .drawer-content, .popup, #options, #extensionsMenu) {
        scroll-behavior: auto;
        transition-duration: 0.01ms;
        animation-duration: 0.01ms;
        animation-iteration-count: 1;
    }
}

/*
 * 玉兰 · 夜禁宫墙设计令牌
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */

@font-face {
    font-family: "Noto Serif SC Yulan";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notoserifsc/notoserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 200 900;
    font-display: swap;
}

@font-face {
    font-family: "Long Cang Yulan";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/longcang/longcang.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --yl-ink: #110b0b;
    --yl-ink-soft: #191312;
    --yl-cinnabar: #b73f42;
    --yl-cinnabar-deep: #5d181d;
    --yl-blue: #436c85;
    --yl-apricot: #de9960;
    --yl-jade: #82b29b;
    --yl-paper: #eee6cb;
    --yl-paper-muted: #cbbf9e;
    --yl-panel: rgba(13, 11, 10, 0.96);
    --yl-panel-soft: rgba(25, 19, 18, 0.90);
    --yl-char: rgba(55, 10, 14, 0.92);
    --yl-user: rgba(8, 25, 31, 0.92);
    --yl-line: rgba(238, 230, 203, 0.22);
    --yl-line-red: rgba(183, 63, 66, 0.68);
    --yl-line-jade: rgba(130, 178, 155, 0.58);
    --yl-focus: rgba(222, 153, 96, 0.88);
    --yl-success: #82b29b;
    --yl-warning: #de9960;
    --yl-error: #d86a6c;
    --yl-info: #6d95aa;
    --yl-radius-xs: 3px;
    --yl-radius-sm: 7px;
    --yl-radius-md: 12px;
    --yl-shadow: 0 20px 54px rgba(0, 0, 0, 0.46);
    --yl-shadow-soft: 0 9px 26px rgba(0, 0, 0, 0.34);
    --yl-font-body: "Noto Serif SC Yulan", "Noto Serif SC", "Source Han Serif SC", serif;
    --yl-font-display: "Long Cang Yulan", "Long Cang", "Noto Serif SC Yulan", serif;
    --yl-font-mono: "Courier Prime", "Cascadia Mono", Consolas, monospace;
    --yl-background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-night-wall-background.png");
    --yl-character-branch: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-character-branch.png");
    --yl-user-branch: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-user-branch.png");
    --yl-top-nine-atlas: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-top-nine-atlas-v5.png");
    --yl-lattice-frame: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-lattice-frame-v4.png");
    --yl-range-ruler: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-range-ruler-v4.png");
    --yl-range-thumb: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-range-thumb-v4.png");
    --yl-options-icon: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-options-bamboo.png");
    --yl-magic-icon: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-magic-flower-brush.png");
    --yl-send-icon: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-send-flying-letter.png");
    --yl-stop-icon: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/330ac2ec2632ecbf33476bfdee83a44665fa670b/assets/%E7%8E%89%E5%85%B0/yulan-stop-seal.png");
    --yl-speed: 150ms;
}

/* W01 · 连续宫墙编辑长卷。题头属于每条消息并 normal 滚动。 */

#chat {
    color: var(--yl-paper);
    border: 0;
    background-color: rgba(17, 11, 11, 0.74);
    background-image:
        linear-gradient(90deg, rgba(183, 63, 66, 0.06), transparent 26%, transparent 74%, rgba(67, 108, 133, 0.07)),
        linear-gradient(rgba(238, 230, 203, 0.018), rgba(238, 230, 203, 0.018));
    box-shadow: inset 0 0 90px rgba(0, 0, 0, 0.32);
    text-shadow: none;
}

#chat .mes:not([is_system="true"]) {
    position: relative;
    box-sizing: border-box;
    align-items: flex-start;
    gap: 14px;
    margin-block: 0;
    padding: 24px clamp(16px, 3vw, 42px) 30px;
    color: var(--yl-paper);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    background-image: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes[is_user="true"] {
    padding-block: 18px 22px;
    background-color: rgba(8, 25, 31, 0.28);
    background-image: linear-gradient(90deg, transparent, rgba(67, 108, 133, 0.10) 28%, rgba(130, 178, 155, 0.05) 72%, transparent);
}

#chat .mes:not(.smallSysMes) > .mesAvatarWrapper {
    box-sizing: border-box;
    display: grid;
    flex: 0 0 68px;
    grid-auto-rows: max-content;
    justify-items: center;
    align-content: start;
    width: 68px;
    min-width: 68px;
    max-width: 68px;
    margin-top: 10px;
    text-align: center;
}

#chat .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar {
    box-sizing: border-box;
    display: grid;
    flex: none;
    place-items: center;
    width: 58px;
    min-width: 58px;
    max-width: 58px;
    height: 58px;
    min-height: 58px;
    max-height: 58px;
    aspect-ratio: 1 / 1;
    margin-inline: auto;
    padding: 0;
    border: 1px solid var(--yl-apricot);
    border-radius: 50%;
    background-color: var(--yl-ink);
    box-shadow: 0 0 0 3px var(--yl-ink), 0 0 0 4px rgba(183, 63, 66, 0.86), 0 8px 18px rgba(0, 0, 0, 0.34);
    line-height: 0;
}

#chat .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
    box-sizing: border-box;
    display: block;
    width: 100%;
    min-width: 100%;
    max-width: 100%;
    height: 100%;
    min-height: 100%;
    max-height: 100%;
    aspect-ratio: 1 / 1;
    margin: 0;
    border-radius: 50%;
    object-fit: cover;
    object-position: 50% 50%;
}

#chat .mes:not(.smallSysMes) > .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    box-sizing: border-box;
    width: 100%;
    text-align: center;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar {
    border-color: var(--yl-jade);
    box-shadow: 0 0 0 3px var(--yl-ink), 0 0 0 4px rgba(67, 108, 133, 0.88), 0 8px 18px rgba(0, 0, 0, 0.34);
}

#chat .mes > .mes_block {
    box-sizing: border-box;
    flex: 1 1 auto;
    width: auto;
    min-width: 0;
    max-width: 100%;
    margin: 0;
}

#chat .mes .ch_name {
    box-sizing: border-box;
    min-height: clamp(104px, 8vw, 128px);
    margin-bottom: 8px;
    padding: 11px 12px 22px;
    border: 0;
    background-image: var(--yl-character-branch);
    background-origin: content-box;
    background-position: right 12px center;
    background-repeat: no-repeat;
    background-size: contain;
}

#chat .mes[is_user="true"] .ch_name {
    min-height: clamp(92px, 7vw, 112px);
    background-image: var(--yl-user-branch);
    background-size: contain;
}

#chat .mes .name_text {
    color: var(--yl-apricot);
    font-family: var(--yl-font-display);
    font-size: 1.58em;
    font-weight: 400;
    letter-spacing: 0.12em;
    text-shadow: 0 2px 10px rgba(0, 0, 0, 0.42);
}

#chat .mes[is_user="true"] .name_text { color: var(--yl-jade); }

#chat .mes .timestamp,
#chat .mes :is(.mes_timer, .tokenCounterDisplay, .mesIDDisplay) {
    color: var(--yl-paper-muted);
    font-family: var(--yl-font-body);
    font-size: 0.78em;
    letter-spacing: 0.06em;
    opacity: 0.88;
    text-shadow: none;
}

#chat .mes :is(.mes_buttons, .mes_edit_buttons) { color: var(--yl-paper-muted); }

#chat .mes :is(.mes_button, .menu_button) {
    color: var(--yl-paper-muted);
    border-radius: var(--yl-radius-xs);
    background-color: transparent;
    text-shadow: none;
}

#chat .mes :is(.mes_button, .menu_button):hover,
#chat .mes :is(.mes_button, .menu_button):focus-visible {
    color: var(--yl-apricot);
    background-color: rgba(183, 63, 66, 0.18);
    filter: none;
}

#chat .mes[is_user="true"] :is(.mes_button, .menu_button):hover,
#chat .mes[is_user="true"] :is(.mes_button, .menu_button):focus-visible {
    color: var(--yl-jade);
    background-color: rgba(67, 108, 133, 0.22);
}

#chat .mes_reasoning_details {
    margin-block: 12px;
    padding: 10px 12px;
    color: var(--yl-paper);
    border: 0;
    border-radius: 0;
    background-color: rgba(17, 11, 11, 0.38);
    box-shadow: inset 3px 0 0 rgba(222, 153, 96, 0.30);
}

#chat .mes_reasoning_summary {
    color: var(--yl-apricot);
    background-color: rgba(183, 63, 66, 0.16);
    text-shadow: none;
}

#chat .mes_reasoning { color: var(--yl-paper-muted); background-color: transparent; }

#chat .mes[is_system="true"],
#chat .smallSysMes {
    margin-block: 9px;
    color: var(--yl-paper-muted);
    border: 1px solid var(--yl-line);
    border-left: 4px solid var(--yl-blue);
    border-radius: var(--yl-radius-xs);
    background-color: rgba(13, 11, 10, 0.78);
    box-shadow: none;
    text-shadow: none;
}

#chat :is(.swipe_left, .swipe_right, .swipes-counter) {
    color: var(--yl-jade);
    text-shadow: 0 0 10px rgba(130, 178, 155, 0.30);
}

/* T02 · 夜禁宫墙编辑排版，只作用于聊天正文语义元素。 */

#chat .mes_text {
    box-sizing: border-box;
    width: min(100%, 88ch);
    min-width: 0;
    margin-inline: auto;
    color: var(--yl-paper);
    font-family: var(--yl-font-body);
    font-size: 1em;
    line-height: 1.9;
    letter-spacing: 0.025em;
    overflow-wrap: anywhere;
    text-shadow: none;
}

#chat .mes_text :is(p, ul, ol, blockquote, pre, table, details) {
    margin-block: 0.82em;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    color: var(--yl-apricot);
    font-family: var(--yl-font-display);
    font-weight: 400;
    letter-spacing: 0.12em;
    line-height: 1.3;
    text-shadow: none;
}

#chat .mes_text h1 {
    padding-bottom: 0.35em;
    border-bottom: 1px solid var(--yl-line-red);
    font-size: 1.75em;
}

#chat .mes_text :is(em, i) { color: var(--yl-paper-muted); }
#chat .mes_text :is(strong, b) { color: var(--yl-apricot); font-weight: 700; }

#chat .mes_text blockquote {
    padding: 0.72em 1em;
    color: var(--yl-paper-muted);
    border-left: 4px solid var(--yl-jade);
    border-radius: 0 var(--yl-radius-sm) var(--yl-radius-sm) 0;
    background-color: rgba(67, 108, 133, 0.16);
}

#chat .mes_text :is(code, pre) { font-family: var(--yl-font-mono); }

#chat .mes_text code {
    padding: 0.12em 0.38em;
    color: var(--yl-apricot);
    border: 1px solid var(--yl-line);
    border-radius: 3px;
    background-color: rgba(17, 11, 11, 0.78);
}

#chat .mes_text pre {
    max-width: 100%;
    padding: 0.92em 1em;
    color: var(--yl-paper);
    border: 1px solid var(--yl-line-red);
    border-radius: var(--yl-radius-sm);
    background-color: rgba(10, 9, 8, 0.94);
    overflow-x: auto;
}

#chat .mes_text pre code { padding: 0; color: inherit; border: 0; background: transparent; }

#chat .mes_text table {
    display: block;
    max-width: 100%;
    border-collapse: collapse;
    overflow-x: auto;
}

#chat .mes_text :is(th, td) { padding: 0.54em 0.72em; border: 1px solid var(--yl-line); }
#chat .mes_text th { color: var(--yl-paper); background-color: rgba(183, 63, 66, 0.34); }

#chat .mes_text hr {
    height: 1px;
    margin-block: 1.6em;
    border: 0;
    background-image: linear-gradient(90deg, transparent, var(--yl-cinnabar), var(--yl-apricot), var(--yl-jade), transparent);
}

#chat .mes_text a { color: var(--yl-jade); text-underline-offset: 0.18em; }

#chat .mes_text img,
#chat .mes_media_wrapper img {
    max-width: 100%;
    border: 1px solid var(--yl-line-red);
    border-radius: var(--yl-radius-sm);
}

/* W02 · 在真实 .drawer-icon 的 FontAwesome 位置原位替换九件古物。 */

#top-bar {
    min-height: 66px;
    color: var(--yl-paper-muted);
    border: 0;
    border-bottom: 1px solid rgba(222, 153, 96, 0.34);
    border-radius: 0;
    background-color: rgba(13, 11, 10, 0.92);
    background-image: linear-gradient(90deg, rgba(183, 63, 66, 0.11), transparent 22%, transparent 78%, rgba(67, 108, 133, 0.11));
    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
    text-shadow: none;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) {
    min-width: 0;
    background: transparent;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle {
    box-sizing: border-box;
    display: grid;
    place-items: center;
    width: 58px;
    height: 66px;
    margin-inline: auto;
    padding: 7px 0 0;
    color: transparent;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    text-shadow: none;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle > .drawer-icon {
    box-sizing: border-box;
    display: grid;
    place-items: center;
    width: 54px;
    height: 54px;
    padding: 0;
    color: transparent;
    border: 0;
    background: transparent;
    font-size: 0;
    line-height: 0;
    opacity: 0.84;
    filter: none;
    text-shadow: none;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle > .drawer-icon::before {
    content: "" !important;
    display: block;
    width: 54px;
    height: 54px;
    background-color: transparent;
    background-image: var(--yl-top-nine-atlas);
    background-repeat: no-repeat;
    background-size: 300% 300%;
    filter: saturate(0.94) brightness(0.99);
    transform-origin: center;
    transition: filter var(--yl-speed) ease, transform var(--yl-speed) ease;
}

#ai-config-button > .drawer-toggle > .drawer-icon::before { background-position: 0 0; }
#sys-settings-button > .drawer-toggle > .drawer-icon::before { background-position: 50% 0; }
#advanced-formatting-button > .drawer-toggle > .drawer-icon::before { background-position: 100% 0; }
#WI-SP-button > .drawer-toggle > .drawer-icon::before { background-position: 0 50%; }
#user-settings-button > .drawer-toggle > .drawer-icon::before { background-position: 50% 50%; }
#backgrounds-button > .drawer-toggle > .drawer-icon::before { background-position: 100% 50%; }
#extensions-settings-button > .drawer-toggle > .drawer-icon::before { background-position: 0 100%; }
#persona-management-button > .drawer-toggle > .drawer-icon::before { background-position: 50% 100%; }
#rightNavHolder > .drawer-toggle > .drawer-icon::before { background-position: 100% 100%; }

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:hover {
    background-color: transparent;
    box-shadow: none;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:hover > .drawer-icon::before,
#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:focus-visible > .drawer-icon::before {
    filter: saturate(1.02) brightness(1.10);
    transform: none;
}

#top-settings-holder .drawer-icon.openIcon {
    opacity: 1;
    filter: none;
}

#top-settings-holder .drawer-icon.openIcon::before {
    filter: saturate(1.03) brightness(1.12);
}

/* W03 · 竹简菜单、花笔魔法、飞笺发送与印章停止。 */

#send_form {
    position: relative;
    color: var(--yl-paper);
    border: 1px solid var(--yl-line-red);
    border-radius: var(--yl-radius-sm);
    background-color: rgba(13, 11, 10, 0.97);
    background-image: linear-gradient(120deg, rgba(183, 63, 66, 0.18), transparent 46%, rgba(67, 108, 133, 0.13));
    box-shadow: inset 5px 0 0 var(--yl-cinnabar), var(--yl-shadow-soft);
    text-shadow: none;
}

#send_form::before,
#send_form::after {
    position: absolute;
    color: var(--yl-apricot);
    font-family: var(--yl-font-display);
    line-height: 1;
    text-shadow: none;
}

#send_form::before { content: "竹"; top: 5px; left: 8px; font-size: 11px; }
#send_form::after { content: "兰"; right: 8px; bottom: 6px; color: var(--yl-jade); font-size: 13px; }

#send_form:focus-within {
    border-color: var(--yl-apricot);
    box-shadow: inset 5px 0 0 var(--yl-apricot), 0 0 0 2px rgba(222, 153, 96, 0.12), var(--yl-shadow-soft);
}

#send_textarea {
    margin: 0;
    padding: 11px 14px;
    color: var(--yl-paper);
