#right-nav-panel :is(.character_select, .group_select, .avatar-container):hover { color: var(--yl-paper); border-color: var(--yl-apricot); background-color: rgba(55, 10, 14, 0.66); filter: none; }
#right-nav-panel .avatar img { border: 1px solid var(--yl-jade); box-shadow: 0 0 0 3px var(--yl-ink), 0 0 0 4px var(--yl-blue); }

#right-nav-panel :is(#tagList, .tags, .tags_inline) .tag {
    color: var(--yl-ink) !important;
    border-color: var(--yl-apricot) !important;
    border-radius: 999px 4px 999px 4px !important;
    background-color: var(--yl-jade) !important;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#right-nav-panel :is(.character_select, .group_select).selected { border-color: var(--yl-cinnabar); box-shadow: inset 4px 0 0 var(--yl-cinnabar); }

/* W13 · 弹窗、菜单、下拉与通知。 */

:is(.popup, .popup-content, .popup-body, .popper-modal) {
    color: var(--yl-paper);
    border-color: var(--yl-line-red);
    border-radius: var(--yl-radius-sm);
    background-color: rgba(13, 11, 10, 0.99);
    background-image: linear-gradient(135deg, rgba(183, 63, 66, 0.18), transparent 48%);
    box-shadow: var(--yl-shadow);
    text-shadow: none;
}

:is(.list-group, .options-content, .dropdown-content, .select2-dropdown, .select2-results) {
    color: var(--yl-paper);
    border-color: var(--yl-line);
    border-radius: var(--yl-radius-sm);
    background-color: var(--yl-ink);
    box-shadow: var(--yl-shadow-soft);
    text-shadow: none;
}

:is(.select2-results__option, .dropdown-item, .list-group-item):hover,
:is(.select2-results__option, .dropdown-item, .list-group-item)[aria-selected="true"] { color: var(--yl-ink); background-color: var(--yl-apricot); }

body #toast-container > .toast {
    color: var(--yl-paper);
    border: 1px solid var(--yl-line);
    border-left: 5px solid var(--yl-info);
    border-radius: var(--yl-radius-xs);
    background-color: rgba(13, 11, 10, 0.99);
    background-position: 14px center;
    background-repeat: no-repeat;
    background-size: 18px 18px;
    box-shadow: var(--yl-shadow-soft);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

body #toast-container > .toast-info { border-left-color: var(--yl-info); }
body #toast-container > .toast-success { border-left-color: var(--yl-success); }
body #toast-container > .toast-warning { border-left-color: var(--yl-warning); }
body #toast-container > .toast-error { border-left-color: var(--yl-error); }

body #toast-container > .toast :is(.toast-title, .toast-message, .toast-close-button) { color: var(--yl-paper); opacity: 1; text-shadow: none; }
body #toast-container > .toast .toast-progress { background-color: var(--yl-cinnabar); opacity: 0.76; }

.popup :is(.popup-button-ok, .popup-button-confirm) { color: var(--yl-ink); border-color: var(--yl-apricot); background-color: var(--yl-apricot); }
.popup :is(.popup-button-cancel, .popup-button-negative) { color: var(--yl-paper); border-color: var(--yl-line); background-color: var(--yl-blue); }

/* W14 · 保留官方抽屉几何，仅压缩本主题内部密度。 */

@media (max-width: 700px) {
    #bg1,
    #bg_custom { background-position: center top; }

    #chat { background-color: rgba(17, 11, 11, 0.94); }

    #chat .mes:not([is_system="true"]) {
        gap: 8px;
        margin-block: 0;
        padding: 13px 10px 14px;
        border-radius: 0;
    }

    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper {
        flex-basis: 50px;
        width: 50px;
        min-width: 50px;
        max-width: 50px;
        margin-top: 5px;
    }

    #chat .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar {
        flex: none;
        width: 46px;
        min-width: 46px;
        max-width: 46px;
        height: 46px;
        min-height: 46px;
        max-height: 46px;
        aspect-ratio: 1 / 1;
        box-shadow: 0 0 0 3px var(--yl-ink), 0 0 0 4px var(--yl-cinnabar), 0 6px 14px rgba(0, 0, 0, 0.34);
    }

    #chat .mes[is_user="true"] > .mesAvatarWrapper .avatar {
        box-shadow: 0 0 0 3px var(--yl-ink), 0 0 0 4px var(--yl-blue), 0 6px 14px rgba(0, 0, 0, 0.34);
    }

    #chat .mes > .mes_block { width: auto; min-width: 0; }

    #chat .mes .ch_name {
        min-height: 78px;
        padding: 7px 8px 14px;
        background-position: right 6px center;
        background-size: contain;
    }

    #chat .mes .name_text { font-size: 1.28em; letter-spacing: 0.08em; }
    #chat .mes_text { width: 100%; font-size: 0.95em; line-height: 1.82; }

    #send_form { border-radius: var(--yl-radius-xs); box-shadow: inset 4px 0 0 var(--yl-cinnabar), var(--yl-shadow-soft); }
    #send_textarea { padding: 9px 10px; }
    #top-bar { min-height: 54px; }

    #top-settings-holder > :is(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) > .drawer-toggle {
        width: 42px;
        height: 54px;
        padding-top: 4px;
    }

    #top-settings-holder > :is(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) > .drawer-toggle > .drawer-icon,
    #top-settings-holder > :is(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) > .drawer-toggle > .drawer-icon::before {
        width: 40px;
        height: 40px;
    }

    :is(#left-nav-panel, #user-settings-block) input[type="range"] {
        min-height: 34px;
        padding-inline: 13px;
        background-size: 100% 28px;
    }

    :is(#left-nav-panel, #user-settings-block) input[type="range"]::-webkit-slider-thumb {
        width: 16px;
        height: 22px;
        margin-top: 5px;
        background-size: 44px 44px;
    }

    :is(#left-nav-panel, #user-settings-block) input[type="range"]::-moz-range-thumb {
        width: 16px;
        height: 22px;
        background-size: 44px 44px;
    }

    body:not(.charListGrid) #right-nav-panel #rm_print_characters_block :is(.character_select, .group_select) {
        box-sizing: border-box;
        align-items: center;
        gap: 10px;
        margin-bottom: 7px;
        padding: 7px 9px;
    }

    body:not(.charListGrid) #right-nav-panel #rm_print_characters_block :is(.character_select_container, .group_select_container) {
        flex: 1 1 auto;
        width: auto;
        min-width: 0;
        padding: 2px 0;
        border: 0;
        background: transparent;
        box-shadow: none;
    }
}

/* 远程字体/图片失败时保持纯色、系统字体、栏位 tooltip 与原生交互节点可用。 */

body,
#bg1,
#bg_custom {
    background-color: #110b0b;
}

#chat,
#send_form,
:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) {
    background-color: rgba(13, 11, 10, 0.96);
}

#top-settings-holder :is(.drawer-icon, .interactable),
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop) {
    visibility: visible;
    opacity: 1;
}
